INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','articles','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"articles","title":"Articles: a, an and the","level":"A1","order":6,"summary":"Choose an indefinite, definite or zero article using sound and context.","learningGoals":["One nonspecific item","An identified item","General plural nouns"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"One nonspecific item","explanation":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound.","examples":["a uniform","an hourglass"]},{"title":"An identified item","explanation":"Use the when the listener can identify the item, including a second mention. The also works with identified plural nouns.","examples":["I found a ring. The ring was silver.","Please return the borrowed books."]},{"title":"General plural nouns","explanation":"Usually omit the article before a plural noun when referring to its whole class. In these exercises, — means no article.","examples":["Bicycles need regular maintenance.","The bicycles outside are ours."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-articles","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Articles help the listener identify what a noun refers to. A/an introduces one member of a class; the signals that the referent is identifiable; no article often gives a general plural or uncountable meaning. Start with countability and number, then ask whether the listener can identify the thing."],"rules":[{"title":"One nonspecific item","explanation":"Use a or an before a singular countable noun that is not yet identified. Choose by the next sound: an before a vowel sound and a before a consonant sound.","examples":["a uniform","an hourglass","She found **an** old coin. **The** coin was silver."],"pattern":"**a** uniform · **an** hour","paragraphs":["Choose a or an from the next sound, not simply the next letter. A university starts with a /j/ sound, so it takes a. An hour starts with a vowel sound because h is silent. An adjective can determine the article: a box but an empty box."],"id":"articles-foundation-1","domain":"noun-phrases","referenceIds":["bc-articles","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"An identified item","explanation":"Use the when the listener can identify the item, including a second mention. The also works with identified plural nouns.","examples":["I found a ring. The ring was silver.","Please return the borrowed books.","**Water** freezes, but **the water in this bottle** is warm."],"pattern":"First mention: **a** key → identified again: **the** key","paragraphs":["The does not always require an earlier mention. A shared situation can identify the referent: Please close the door. A defining phrase can also identify it: the keys on the table. The works with singular, plural and uncountable nouns when the intended reference is identifiable."],"id":"articles-foundation-2","domain":"noun-phrases","referenceIds":["bc-articles","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"General plural nouns","explanation":"Usually omit the article before a plural noun when referring to its whole class. In these exercises, — means no article.","examples":["Bicycles need regular maintenance.","The bicycles outside are ours.","He is **a** teacher at **the** school near our house."],"pattern":"**Books** can be expensive. / **The books on this shelf** are mine.","paragraphs":["General plural nouns normally have no article: Dogs need exercise. General uncountable nouns also often have no article: Music helps me relax. A singular count noun normally needs a determiner: I bought a book, not I bought book."],"id":"articles-foundation-3","domain":"noun-phrases","referenceIds":["bc-articles","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"Names and fixed institutional expressions require extra learning. Most country and city names have no article, but rivers, seas and ranges commonly take the. In British English, at school can describe attendance, while at the school can identify the site. American in the hospital is normal usage.","examples":["She found **an** old coin. **The** coin was silver.","**Water** freezes, but **the water in this bottle** is warm.","He is **a** teacher at **the** school near our house."],"id":"articles-foundation-4","domain":"noun-phrases","referenceIds":["bc-articles","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"domain":"noun-phrases","id":"generic-reference","title":"General reference: a tiger, the tiger and tigers","explanation":"General statements can use different noun-phrase types. A plural without an article is a common way to refer to a class generally. A/an can describe a representative member. The + singular can refer to a species, invention or class in suitable formal contexts. These forms overlap but are not interchangeable in every predicate.","pattern":"**Tigers** need space. / **A tiger** is a powerful animal.","examples":["**The telephone** changed communication.","**Music** can affect our mood."],"commonMistakes":["A representative individual cannot replace a species-level reference mechanically: The tiger is endangered does not mean that one unspecified tiger is endangered."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"noun-phrases","id":"definiteness-beyond-mention","title":"Shared knowledge, unique reference and associative the","explanation":"The signals that the intended referent can be identified, not merely that a noun has appeared before. Identification can come from the situation, shared knowledge, an attached description or association with something already introduced. A/an introduces one member without requiring the listener to identify which.","pattern":"We entered a house. **The roof** was leaking.","examples":["Please close **the door**.","She is **the person who called yesterday**."],"commonMistakes":["A defining phrase does not always force the: I need a book that explains this introduces any suitable book rather than a uniquely identified one."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**a** uniform · **an** hour","First mention: **a** key → identified again: **the** key","**Books** can be expensive. / **The books on this shelf** are mine."],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["demonstratives"],"readingReferenceIds":["bc-articles","pcc-esol","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='articles'
